<div class="profile-heading"><div><h1><?= htmlspecialchars(trim($student['first_name'].' '.($student['last_name']??'')),ENT_QUOTES,'UTF-8') ?></h1><p><strong>Username:</strong> <?= htmlspecialchars($student['username'],ENT_QUOTES,'UTF-8') ?></p><p><strong>Email:</strong> <?= htmlspecialchars($student['email']??'—',ENT_QUOTES,'UTF-8') ?></p><p><strong>Phone:</strong> <?= htmlspecialchars($student['phone']??'—',ENT_QUOTES,'UTF-8') ?></p><p><strong>Address:</strong> <?= htmlspecialchars(implode(', ',array_filter([$student['address_line1'],$student['address_line2'],$student['city'],$student['state_name'],$student['postal_code']])),ENT_QUOTES,'UTF-8') ?: '—' ?></p><p><strong>Country:</strong> <?= htmlspecialchars($country,ENT_QUOTES,'UTF-8') ?></p><p><strong>Guardian:</strong> <?= htmlspecialchars($student['guardian_name']??'—',ENT_QUOTES,'UTF-8') ?><?= $student['guardian_phone']?' ('.htmlspecialchars($student['guardian_phone'],ENT_QUOTES,'UTF-8').')':'' ?></p></div><?php if(!empty($student['photo_path'])): ?><img class="profile-photo" src="<?= htmlspecialchars($student['photo_path'],ENT_QUOTES,'UTF-8') ?>" alt="Profile photo of <?= htmlspecialchars($student['first_name'],ENT_QUOTES,'UTF-8') ?>"><?php endif; ?></div><h2>Profile details</h2><p><?= !empty($student['profile_details']) ? nl2br(htmlspecialchars($student['profile_details'],ENT_QUOTES,'UTF-8')) : 'Not provided.' ?></p><p><strong>Assignment:</strong> <?= htmlspecialchars($student['assignment_status'],ENT_QUOTES,'UTF-8') ?> from <?= htmlspecialchars($student['start_date'],ENT_QUOTES,'UTF-8') ?><?= $student['end_date']?' to '.htmlspecialchars($student['end_date'],ENT_QUOTES,'UTF-8'):'' ?></p><p><a class="button" href="/Tuman/teacher/student-edit.php?id=<?= $id ?>">Edit profile</a> <a href="/Tuman/teacher/students.php">Back to students</a></p>
